  viga('VA-S', [GS, YO], [GS, YE], VA, ZA, 'Viga perimetral de arriba, sur', nota); viga('VA-N', [GN, YO], [GN, YE], VA, ZA, 'Viga perimetral de arriba, norte', nota);
